action.command:
JS=$(grep -o 'src="[^"]*\.js"' /tmp/root.html | head -1 | sed 's/src="//;s/"//'); echo "JS entry: $JS"; curl -s -o /tmp/app.js -w "JS entry: %{http_code} (size %{size_download})
" -H 'Host: localhost' "http://localhost:3000${JS}"; head -c 300 /tmp/app.js; echo; echo "=== auth endpoints ==="; curl -s -o /dev/null -w "api root: %{http_code}
" -H 'Host: localhost' http://localhost:3000/api/; curl -s -w "
auth login route: %{http_code} -> %{redirect_url}
" -H 'Host: localhost' http://localhost:3000/api/auth/login -o /tmp/authlogin.json; head -c 400 /tmp/authlogin.json 2>/dev/null; echo
